"""Render original arcade cards and a formation pitch in notebooks or browsers."""
from html import escape
import json
from .engine import rate_team, FORMATIONS

CSS='''
.ee{--gold:#e3b957;--muted:#9aada5;--line:#33433b;color:#f5f2e9;background:#09100e;font:14px/1.5 ui-monospace,Consolas,monospace;padding:24px;border:1px solid var(--line);box-sizing:border-box}.ee *{box-sizing:border-box}.ee h1,.ee h2,.ee h3{color:#e3b957!important;font-family:Impact,'Arial Narrow',sans-serif!important;letter-spacing:.12em;font-weight:400!important}.ee h1{font-size:48px;margin:0}.ee h2{font-size:23px;margin:0 0 12px}.ee h3{font-size:18px;margin:0}.ee .muted{color:var(--muted)}.ee .small{font-size:11px}.ee .caps{text-transform:uppercase;letter-spacing:.16em}.ee .cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.ee .card{background:linear-gradient(145deg,#273429,#111c17 60%);border:1px solid #a0874a;padding:17px;min-height:210px;position:relative;overflow:hidden}.ee .card:after{content:'';position:absolute;width:130px;height:130px;border:1px solid #e3b95720;transform:rotate(45deg);right:-60px;top:35px;pointer-events:none}.ee .card .ovr{font:48px/1 Impact,'Arial Narrow',sans-serif;color:var(--gold)}.ee .card .pos{font-size:13px;color:var(--gold)}.ee .card .name{font-size:17px;font-weight:bold;line-height:1.25;margin:16px 0 8px;overflow-wrap:anywhere}.ee .card .stats{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;font-size:11px;border-top:1px solid #6a5f40;padding-top:10px}.ee .card .stats b{font-size:14px;color:#e9d49b}.ee .badge{display:inline-block;border:1px solid #475c50;padding:3px 8px;color:#b8d1c2;font-size:10px;margin:2px 0}.ee .team-layout{display:grid;grid-template-columns:1.5fr 1fr;gap:22px}.ee .pitch{position:relative;min-width:0;width:100%;aspect-ratio: .78;background:repeating-linear-gradient(0deg,#142f23 0%,#142f23 12.5%,#163526 12.5%,#163526 25%);border:1px solid #517460;min-height:530px}.ee .pitch:before{content:'';position:absolute;inset:5%;border:1px solid #95b29a70;pointer-events:none}.ee .half{position:absolute;top:50%;left:5%;right:5%;border-top:1px solid #95b29a70}.ee .circle{position:absolute;width:26%;aspect-ratio:1;border:1px solid #95b29a70;left:37%;top:40%;border-radius:50%}.ee .box{position:absolute;width:46%;height:17%;left:27%;border:1px solid #95b29a70}.ee .box.top{top:5%;border-top:0}.ee .box.bottom{bottom:5%;border-bottom:0}.ee .pin{position:absolute;transform:translate(-50%,-50%);text-align:center;width:24%;font-size:10px;line-height:1.25}.ee .pin .number{display:block;margin:0 auto 5px;background:#e3b957;color:#10170f;width:32px;height:32px;line-height:32px;border-radius:50%;font-weight:bold;font-size:13px;box-shadow:0 2px 8px #0005}.ee .pin .pname{display:inline-block;background:#08140ee0;padding:3px 5px;max-width:100%;overflow-wrap:anywhere;color:#f3f0e4}.ee .pin .role{color:#c2d7c8;font-size:9px}.ee .metric{display:flex;justify-content:space-between;border-bottom:1px solid #33433b;padding:8px 0}.ee .bar{height:4px;background:#33433b;margin-bottom:8px}.ee .bar>i{display:block;height:100%;background:#e3b957}.ee .reserve{border:1px solid #33433b;padding:10px;margin-top:8px;font-size:12px}.ee .score{font:64px/1 Impact,'Arial Narrow',sans-serif;letter-spacing:.1em;color:#e3b957;text-align:center;margin:15px}.ee .timeline{max-height:260px;overflow:auto;border-top:1px solid #33433b;padding-top:8px}.ee .event{border-bottom:1px solid #25352b;padding:6px;font-size:12px}.ee details{margin:12px 0}.ee summary{color:#b5cbbb;cursor:pointer}.ee table{width:100%;border-collapse:collapse;color:#eee!important;background:transparent!important}.ee td,.ee th{text-align:left;padding:7px;border-bottom:1px solid #33433b}.ee a{color:#e3b957}@media(max-width:650px){.ee{padding:15px}.ee .cards{gap:7px}.ee .card{padding:10px}.ee .card .name{font-size:13px}.ee .team-layout{grid-template-columns:1fr}.ee .pitch{min-height:450px}}'''

def card_html(p):
    gk='GK' in p['positions']
    keys=['gk_diving','gk_handling','gk_kicking','gk_reflexes','gk_speed','gk_positioning'] if gk else ['pace','shooting','passing','dribbling','defending','physical']
    labels=['DIV','HAN','KIC','REF','SPD','POS'] if gk else ['PAC','SHO','PAS','DRI','DEF','PHY']
    stats=''.join(f'<span><b>{int(p[k]) if p.get(k) is not None else "?"}</b> {label}</span>' for k,label in zip(keys,labels))
    origin='ICON / HERO' if 'icon-reconstruction' in p['lineage'] else p['season']
    return f'<article class="card"><div class="ovr">{int(p["overall"])}</div><div class="pos">{escape(" / ".join(p["positions"]))}</div><div class="name">{escape(p["name"])}</div><div class="small muted">{escape(p.get("nation",""))} · {escape(p["era"])}</div><div class="badge">{escape(origin)}</div><div class="stats">{stats}</div><div class="small muted" style="margin-top:10px">{escape(p.get("club",""))}</div></article>'

def pitch_html(team):
    pins=''
    for s in team['starters']:
        p=s['player']
        pins+=f'<div class="pin" style="left:{s["x"]}%;top:{s["y"]}%"><span class="number">{int(p["overall"])}</span><span class="pname">{escape(p["name"])}</span><div class="role">{s["slot"]} · {s["fit"]:.0%} fit</div></div>'
    return f'<div class="pitch"><div class="half"></div><div class="circle"></div><div class="box top"></div><div class="box bottom"></div>{pins}</div>'

def team_html(team):
    r=rate_team(team)
    bars=''.join(f'<div class="metric"><span>{label}</span><b>{r[key]:.1f}</b></div><div class="bar"><i style="width:{min(100,max(0,r[key])):.1f}%"></i></div>' for key,label in [('attack','Attack'),('control','Midfield control'),('defence','Defence'),('keeper','Goalkeeper')])
    bench=''.join(f'<div class="reserve"><b>{int(p["overall"])}</b> {escape(p["name"])} <span class="muted">{" / ".join(p["positions"])}</span></div>' for p in team['bench'])
    return f'<div class="team-layout">{pitch_html(team)}<div><h2>{escape(team["formation"])}</h2><div>{escape(team["manager"]["name"])}</div><div class="muted small">{escape(team["manager"]["style"])}</div><div style="margin:20px 0">{bars}</div><h3>Four substitutes</h3>{bench}<details><summary>How this squad is rated</summary><p class="small muted">Role fit: {r["role_fit"]:.0%}. Chemistry and tactics use editable game settings. Missing stamina uses {team["config"]["default_stamina"]:.0f} for {len(r["stamina_fallbacks"])} players. This model has not been calibrated to historical results.</p></details></div></div>'

def result_html(result):
    events=''.join(f'<div class="event"><b>{e["minute"]}′</b> {"●" if e["type"]=="Goal" else "↔"} {escape(e["player"])} <span class="muted">{e["side"]} · {e["type"]}{(" · xG "+format(e["xg"],".2f")) if "xg" in e else " · off: "+escape(e["out"])}</span></div>' for e in result['events'] if e['type'] in ['Goal','Substitution'])
    return f'<div class="score">{result["home_goals"]} : {result["away_goals"]}</div><div class="metric"><span>Shot xG</span><b>{result["home_xg"]:.2f} : {result["away_xg"]:.2f}</b></div><div class="metric"><span>Shots</span><b>{result["home_shots"]} : {result["away_shots"]}</b></div><div class="metric"><span>Possession proxy</span><b>{result["home_possession"]:.0f}% : {result["away_possession"]:.0f}%</b></div><div class="timeline">{events or "No goals or substitutions."}</div><p class="small muted">{escape(result["label"])}</p>'

def wrap(body):return '<style>'+CSS+'</style><div class="ee">'+body+'</div>'
